"""In-memory task store with JSON persistence."""
import json
from dataclasses import dataclass, field, asdict
from datetime import date


@dataclass
class Task:
    id: int
    title: str
    done: bool = False
    due: str | None = None  # ISO date "YYYY-MM-DD"
    tags: list[str] = field(default_factory=list)


class Store:
    def __init__(self):
        self.tasks: list[Task] = []

    def add(self, title, due=None, tags=None):
        new_id = len(self.tasks) + 1
        task = Task(new_id, title, due=due, tags=tags or [])
        self.tasks.append(task)
        return task

    def get(self, task_id):
        for t in self.tasks:
            if t.id == task_id:
                return t
        raise KeyError(task_id)

    def remove(self, task_id):
        self.tasks.remove(self.get(task_id))

    def complete(self, task_id):
        self.get(task_id).done = True

    def overdue(self, today=None):
        today = today or date.today().isoformat()
        return [t for t in self.tasks if t.due and t.due <= today]

    def save(self, path):
        with open(path, "w") as f:
            json.dump([asdict(t) for t in self.tasks], f)

    @classmethod
    def load(cls, path):
        store = cls()
        with open(path) as f:
            for row in json.load(f):
                store.tasks.append(Task(**row))
        return store

"""Tiny command line: python -m todo.cli <db.json> <command> [args]"""
import os
import sys

from .store import Store


def main(argv=None):
    argv = argv if argv is not None else sys.argv[1:]
    db, cmd, *args = argv
    store = Store.load(db) if os.path.exists(db) else Store()
    if cmd == "add":
        task = store.add(args[0])
        print(f"added {task.id}")
    elif cmd == "done":
        store.complete(int(args[0]))
    elif cmd == "list":
        for t in store.tasks:
            print(f"{t.id} [{'x' if t.done else ' '}] {t.title}")
    else:
        print(f"unknown command {cmd}", file=sys.stderr)
        return 2
    store.save(db)
    return 0


if __name__ == "__main__":
    sys.exit(main())

